		static DataTable GetTableSchema()
	    {
	        DataTable dt = new DataTable();
	        dt.Columns.AddRange(new DataColumn[]
	        {
	            new DataColumn("LotSN", typeof(string)),
	            new DataColumn("CheckStatus", typeof(string)),
	            new DataColumn("CheckDesc", typeof(string))
	        });
	        return dt;
	    }
		
		#region 获取目录所有文本文件 
	    private List<string> GetTextFiles(string dir)
	    {
	        // 用 *.* 取全部文件，再手动过滤，兼容 .txt 和 .txt_已读 / .txt_已读(1)
	        string[] files = Directory.GetFiles(dir, "*.*");	

	        List<string> strList = new List<string>();

	        try
	        {
	            for (int i = 0; i < files.Length; i++)
	            {
	                string fullName = files[i];
	                string name = Path.GetFileName(fullName);

	                // 只保留文件名中包含 ".txt" 的文件
	                // 兼容：xxx.txt / xxx.txt_已读 / xxx.txt_已读(1) / xxx.txt_已读_已读 ...
	                if (name.IndexOf(".txt", StringComparison.OrdinalIgnoreCase) < 0)
	                {
	                    continue;
	                }

	                FileInfo fi = new FileInfo(fullName);

	                // 过滤"最近 10 秒内创建"的文件，防止读到正在写入的文件
	                if (DateTime.Compare(fi.CreationTime, DateTime.Now.AddSeconds(-10d)) > 0)
	                {
	                    continue;
	                }

	                // 过滤"最近 10 秒内修改"的文件，双重保险
	                if (DateTime.Compare(fi.LastWriteTime, DateTime.Now.AddSeconds(-10d)) > 0)
	                {
	                    continue;
	                }

	                strList.Add(fullName);
	            }
	        }
	        catch (Exception ex)
	        {
	            IsRunning = false;
	            MessageBox.Show(ex.Message);
	        }

	        return strList;	      
	    }
		#endregion 

		private void LoadTextFile(string dir)
	    {
	        List<string> fileList = GetTextFiles(dir);
			string vDir = "";
			string vFileName = "";	

	        if (fileList.Count < 1)
	        {
				IsRunning = false;
	            return;
	        }
			
	        try
	        { 
	            for (int k = fileList.Count - 1; k >= 0; k--)
	            {
					CurrDt.Clear();
					if (File.Exists(fileList[k].ToString()) == false)
	                {
	                    continue;
	                }
					
        			/* 记录并格式化文件创建时间 */
					DateTime rawTime = File.GetCreationTime(fileList[k]);
					string txtCreateTime = rawTime.ToString("yyyy-MM-dd HH:mm:ss");
					Scripter.SetParameterValue("txtCreateTime", txtCreateTime);
										
	                string[] dataLineString = File.ReadAllLines(fileList[k].ToString(), Encoding.UTF8);
					Scripter.SetControlStyle("CheckResult", "TextBox");
					Scripter.SetParameterValue("CheckResult", "");
					
	                if (dataLineString != null)
	                {
	                    int lineNum = dataLineString.Length;
	                    for (int i = 0; i < lineNum; i++)
	                    {
							string strNGDesc = "";
	                        // 把文本文件保存到表里
	                        string[] vField = dataLineString[i].Split(new char[] { ';' });
	                        if (vField != null)
	                        {
	                            if (vField.Length < 2)
	                            {
	                                continue;
	                            }
								DataRow dr = CurrDt.NewRow();
	                            dr[0] = Convert.ToString(vField[0]);  // 条码编号
	                            dr[1] = Convert.ToString(vField[1]);  // 检查状态
								// 多个NG扫描的状态
								for (int m = 2; m < vField.Length - 1; m++)
								{
									strNGDesc = strNGDesc + Convert.ToString(vField[m]);
									if (m != vField.Length - 2)
	                                {
	                                    strNGDesc = strNGDesc + "#";
	                                }
								}	
								dr[2] = strNGDesc;
								CurrDt.Rows.Add(dr);
	                        }
	                    }
						// 判定是OK还是NG
						DataRow[] arrayNG = CurrDt.Select("CheckStatus='NG'");
						
						string fileName = Path.GetFileNameWithoutExtension(fileList[k].ToString());
	                    if (arrayNG.Length < 1)
						{	// 判定OK
							if (AOITestIsOK(fileName.Substring(0, 1)) == -1)
							{
								IsRunning = false;
								return;
							}
						}
						else
						{	// 判定NG	
							if (AOITestIsNG() == -1)
							{
								IsRunning = false;
								return;
							}
						}
	                }

					if (File.Exists(fileList[k].ToString()))
					{
						vDir = Path.GetDirectoryName(fileList[k].ToString()) + @"\YD\";
			            vFileName = Path.GetFileName(fileList[k].ToString());

			            // ===== 手动剥离 _已读 / _已读(1) / _已读_已读 ... 后缀 =====
			            while (true)
			            {
			                // 情况1：以 _已读 结尾
			                if (vFileName.EndsWith("_已读", StringComparison.OrdinalIgnoreCase))
			                {
			                    vFileName = vFileName.Substring(0, vFileName.Length - "_已读".Length);
			                    continue;
			                }

			                // 情况2：以 _已读(数字) 结尾
			                int lastParen = vFileName.LastIndexOf('(');
			                if (lastParen > 0 && vFileName.EndsWith(")", StringComparison.Ordinal))
			                {
			                    string numPart = vFileName.Substring(lastParen + 1, vFileName.Length - lastParen - 2);
			                    bool isAllDigits = numPart.Length > 0;
			                    for (int n = 0; n < numPart.Length; n++)
			                    {
			                        if (!char.IsDigit(numPart[n])) { isAllDigits = false; break; }
			                    }
			                    if (isAllDigits)
			                    {
			                        string beforeParen = vFileName.Substring(0, lastParen);
			                        if (beforeParen.EndsWith("_已读", StringComparison.OrdinalIgnoreCase))
			                        {
			                            vFileName = beforeParen;
			                            continue;
			                        }
			                    }
			                }
			                break;
			            }
			            // ===== 剥离结束 =====

			            if (!Directory.Exists(vDir))
			            {
			                Directory.CreateDirectory(vDir);
			            }

			            // 目标文件名：清理后的原文件名 + _已读
			            string destPath = Path.Combine(vDir, vFileName + "_已读");

			            // 若目标已存在，自动加 (1)(2)... 序号
			            if (File.Exists(destPath))
			            {
			                string nameNoExt = Path.GetFileNameWithoutExtension(vFileName);
			                string ext = Path.GetExtension(vFileName);
			                int seq = 1;
			                do
			                {
			                    destPath = Path.Combine(vDir, string.Format("{0}_已读({1}){2}", nameNoExt, seq, ext));
			                    seq++;
			                }
			                while (File.Exists(destPath));
			            }

				        File.Move(fileList[k].ToString(), destPath);
						fileList.RemoveAt(k);
					}
	            }
				IsRunning = false;
	        }
	        catch (Exception ex)
	        {
				IsRunning = false;
	            MessageBox.Show(ex.Message);
	        }
	    }

		#region PCB良品情况
		private int AOITestIsOK(string PCBType)
		{
			//检测AOI是否有漏板
			IsMakeupNumber(CurrDt.Rows.Count);							
			if (GetReturnValue() != 0)
			{
				return -1;
			}
			
			for (int j = 0; j < CurrDt.Rows.Count; j++)
			{
				Scripter.SetControlStyle("LotSN", "TextBox");
				Scripter.SetParameterValue("LotSN", CurrDt.Rows[j]["LotSN"].ToString());
				
				Scripter.SetControlStyle("ReturnValue", "TextBox");
				Scripter.SetParameterValue("ReturnValue", "-1");
			
				// 1. 调用窗体上的过程弹出错误
				if (!PCBType.Equals("M") && !PCBType.Equals("C"))
				{
					PCBType = "";
				}
				
				string UIPCBType = Scripter.GetParameterValue("PCBType").ToString();
				if (UIPCBType == "")
				{
					Scripter.SetControlStyle("PCBType", "TextBox");
					Scripter.SetParameterValue("PCBType", PCBType);
				}	
				
				if (Scripter.GetParameterValue("Side") == "A")
					Scripter.RunMethod("AOIAutoScan");
				if (Scripter.GetParameterValue("Side") == "AB")
					Scripter.RunMethod("AOIAutoScan");
				if (Scripter.GetParameterValue("Side") == "B")
					Scripter.RunMethod("AOIAutoScanBSide");
				
				Thread.Sleep(300);
				// 2. 停用定时器	
				if (GetReturnValue() != 0)
				{
					return -1;
				}
				// 扫描已经达到拼板数，扫描提交条码
				if (j + 1 == CurrDt.Rows.Count)
				{
					if (!PCBType.Equals("M") && !PCBType.Equals("C"))
					{
						PCBType = "";
					}
					Scripter.SetControlStyle("PCBType", "TextBox");
					Scripter.SetParameterValue("PCBType", PCBType);
					
					Scripter.SetControlStyle("LotSN", "TextBox");
					Scripter.SetParameterValue("LotSN", "SUBMIT");
					// 1. 调用窗体上的过程弹出错误
					if (Scripter.GetParameterValue("Side") == "A")
						Scripter.RunMethod("AOIAutoScan");
					if (Scripter.GetParameterValue("Side") == "AB")
						Scripter.RunMethod("AOIAutoScan");
					if (Scripter.GetParameterValue("Side") == "B")
						Scripter.RunMethod("AOIAutoScanBSide");
					Thread.Sleep(300);
					// 2. 停用定时器		
					if (GetReturnValue() != 0)
					{
						return -1;
					}								
				}
			}
			return 0;
		}
		#endregion

		#region PCB不良情况
		private int AOITestIsNG()
		{
			//检测AOI是否有漏板
			IsMakeupNumber(CurrDt.Rows.Count);	
			string hideList = "";
			if (GetReturnValue() != 0)
			{
				return -1;
			}
			for (int i = 0; i < CurrDt.Rows.Count; i++)
			{
				if (CurrDt.Rows[i]["CheckStatus"].ToString() == "NG")
				{
					Scripter.SetControlStyle("CheckResult", "TextBox");
					Scripter.SetParameterValue("CheckResult", "NG");	
					
					Scripter.SetControlStyle("LotSN", "TextBox");
					Scripter.SetParameterValue("LotSN", CurrDt.Rows[i]["LotSN"].ToString());
					string[] one_NGDesc = CurrDt.Rows[i]["CheckDesc"].ToString().Split(new char[] { '#' });
					if (one_NGDesc.Length < 1)
					{
						IsRunning = false;
						return -1;
					}
					for (int j = 0; j < one_NGDesc.Length; j++)
					{
						if (string.IsNullOrEmpty(one_NGDesc[j]))
	                    {
	                        continue;
	                    }
						hideList = hideList + one_NGDesc[j].Substring(0, one_NGDesc[j].IndexOf("_")) + ","
											+ one_NGDesc[j].Substring((one_NGDesc[j].IndexOf("_") + 1), (one_NGDesc[j].Length - one_NGDesc[j].IndexOf("_") - 1))
											+ ";";
					}
					Scripter.SetControlStyle("HideInfo", "TextBox");
					Scripter.SetParameterValue("HideInfo", hideList);	
					Thread.Sleep(200);
					Scripter.RunMethod("BtnIsNG");	
					Thread.Sleep(300);
					if (GetReturnValue() != 0)
					{
						return -1;
					}	
				}
			}
			return 0;
		}
		#endregion

		#region 判断AOI读取的PCB板数是否足够
		private void IsMakeupNumber(int AOICount)
		{
			Scripter.SetControlStyle("ReturnValue", "TextBox");
			Scripter.SetParameterValue("ReturnValue", "0");
			
			Scripter.SetControlStyle("IsMakeupNumber", "TextBox");
			Scripter.SetParameterValue("IsMakeupNumber", "0");
			
			Scripter.SetControlStyle("MakeUpNumber", "TextBox");
			string MakeUpNumber = Scripter.GetParameterValue("MakeUpNumber");
						
			if (int.Parse(MakeUpNumber) != AOICount)
			{
				Scripter.SetControlStyle("LotSN", "TextBox");
				Scripter.SetParameterValue("LotSN", "MakeupNumber is not enough");
				Scripter.SetControlStyle("IsMakeupNumber", "TextBox");
				Scripter.SetParameterValue("IsMakeupNumber", "-1");
				Thread.Sleep(200);
				if (Scripter.GetParameterValue("Side") == "A")
					Scripter.RunMethod("AOIAutoScan");
				if (Scripter.GetParameterValue("Side") == "B")
					Scripter.RunMethod("AOIAutoScanBSide");
				Thread.Sleep(300);
			}
		}
		#endregion

		#region 预检测，看数据是否有效	
		private int GetReturnValue()
		{			
			Scripter.SetControlStyle("ReturnValue", "TextBox");
			string returnValue = Scripter.GetParameterValue("ReturnValue");
			if (returnValue != "0")
			{
				IsRunning = false;
				return -1;
			}
			else
				return 0;
		}
