		private void aTimer_Tick(object sender, EventArgs e)
        {	
			if (IsRunning == true)
			{
				return;
			}
			try
			{	
				if (Directory.Exists(@FilePath))
				{
					IsRunning = true;
					LoadTextFile(@FilePath);
				}
				else
				{
					aTimer.Stop();
					IsRunning = false;
					Scripter.MESTxnPanel.Controls["btn_BtnStop"].Text = "启用同步";
					MessageBox.Show("文件路径" + FilePath + "不存在，请确认");
				}	
			}
			catch (Exception ex)
            {
				IsRunning = false;
				MessageBox.Show(ex.Message);
            }
        }
