		static DataTable GetTableSchema()
	    {
	        DataTable dt = new DataTable();
	        dt.Columns.AddRange(new DataColumn[]
	        {
	            new DataColumn("LotSN", typeof(string)),
	            new DataColumn("CheckStatus", typeof(string)),
	            new DataColumn("CheckDesc", typeof(string))
	        });
	        return dt;
	    }
		
		#region 获取目录所有文本文件 
	    private List<string> GetTextFiles(string dir)
	    {
			string[] files = Directory.GetFiles(dir, "*.txt");	

	        List<string> strList = new List<string>(files);//files.ToList();
			List<string> strRemove = new List<string>();
			
			try
			{
				for (int i = strList.Count-1 ; i>= 0; i--)
		        {
		            if (strList[i].IndexOf("_已读") != -1)
		            {
						strRemove.Add(strList[i].ToString());
		                continue;
		            }
		            FileInfo fi = new FileInfo(strList[i]);
		            int dtDiff = DateTime.Compare(fi.CreationTime,DateTime.Now.AddMinutes(-1d));
					// 近10秒内生成的文件， 暂不处理
		            if (dtDiff > 0)
		            {
						strRemove.Add(strList[i].ToString());
		                continue;
		            }
		        }
				
//				foreach(string vRemove in strRemove)
//				{
//					strList.Remove(vRemove);
//				}
			}
	        catch (Exception ex)
	        {
				//aTimer.Stop();
				IsRunning=false;
	            MessageBox.Show(ex.Message);
				//Scripter.MESTxnPanel.Controls["btn_BtnStop"].Text = "启用同步";
	        }
	        return strList;	      
	    }
		#endregion 
		//#region 读取文件并自动扫描
		private void LoadTextFile(string dir)
	    {
	        List<string> fileList= GetTextFiles(dir);
			string vDir = "";
			string vFileName = "";	

	        if (fileList.Count < 1)
	        {
				IsRunning=false;
	            return;
	        }
			
	        try
	        { 
	            for (int k = fileList.Count -1; k>=0; k--)
	            {
					CurrDt.Clear();
					if (File.Exists(fileList[k].ToString())==false)
	                {
	                    continue;
	                }
					
        			/* 新增：记录并格式化文件创建时间 */
					DateTime rawTime = File.GetCreationTime(fileList[k]);
					string txtCreateTime = rawTime.ToString("yyyy-MM-dd HH:mm:ss");   // 结果形如 20240625 143015
					Scripter.SetParameterValue("txtCreateTime",txtCreateTime);
										
					
	                string[] dataLineString = File.ReadAllLines(fileList[k].ToString(), Encoding.UTF8);
					Scripter.SetControlStyle("CheckResult","TextBox");
					Scripter.SetParameterValue("CheckResult","");
					
	                if (dataLineString != null)
	                {
	                    int lineNum = dataLineString.Length;
	                    for (int i = 0; i < lineNum; i++)
	                    {
							string strNGDesc = "";
	                        //把文本文件保存到表里
	                        string[] vField = dataLineString[i].Split(new char[] { ';' });
	                        if (vField != null)
	                        {
	                            if (vField.Length<2)
	                            {
	                                continue;
	                            }
								DataRow dr = CurrDt.NewRow();
	                            dr[0] = Convert.ToString(vField[0]);  //条码编号
	                            dr[1] = Convert.ToString(vField[1]);  //检查状态
								//多个NG扫描的状态
								for (int m=2; m < vField.Length - 1; m++)
								{
									strNGDesc = strNGDesc + Convert.ToString(vField[m]);
									if (m != vField.Length - 2)
	                                {
	                                    strNGDesc = strNGDesc + "#";
	                                }
								}	
								dr[2] = strNGDesc;
								CurrDt.Rows.Add(dr);
	                        }
	                    }
						// 判定是OK还是NG
						DataRow[] arrayNG = CurrDt.Select("CheckStatus='NG'");
						
						string fileName = Path.GetFileNameWithoutExtension(fileList[k].ToString());
						//MessageBox.Show("arrayNG.Length:"+arrayNG.Length);
	                    if (arrayNG.Length < 1)
						{	// 判定OK
							if (AOITestIsOK(fileName.Substring(0,1))==-1)
							{
								IsRunning = false;
								return;
							}
						}
						else  
						{	//判定NG	
							if(AOITestIsNG()==-1)
							{
								IsRunning = false;
								return;
							}
						}
						
	                }
					if (File.Exists(fileList[k].ToString()))
					{
	                	//File.Move(fileList[k].ToString(), fileList[k].ToString() + "_已读");	
						vDir = Path.GetDirectoryName(fileList[k].ToString()) + @"\YD\";
			            vFileName = Path.GetFileName(fileList[k].ToString());						
			            if (!Directory.Exists(vDir))
			            {
			                Directory.CreateDirectory(vDir);
			            }
				        File.Move(fileList[k].ToString(), vDir + vFileName  + "_已读");
						fileList.RemoveAt(k);
					}
	            }
				IsRunning = false;
	        }
	        catch (Exception ex)
	        {
				//aTimer.Stop();
				IsRunning=false;
				// MessageBox.Show("ERROR1");
	            MessageBox.Show(ex.Message);
				//Scripter.MESTxnPanel.Controls["btn_BtnStop"].Text = "启用同步";
	        }
	    }
		//#endregion 
		#region PCB良品情况
		private int AOITestIsOK(string PCBType)
		{
			//检测AOI是否有漏板
			IsMakeupNumber(CurrDt.Rows.Count);							
			if(GetReturnValue()!=0)
			{
				return -1;
			}
			
			for (int j=0; j< CurrDt.Rows.Count; j++)
			{
				//MessageBox.Show("Row:"+ CurrDt.Rows.Count.ToString() + "Cuur ROW: " + j.ToString());
				Scripter.SetControlStyle("LotSN","TextBox");
				Scripter.SetParameterValue("LotSN",CurrDt.Rows[j]["LotSN"].ToString());
				
				Scripter.SetControlStyle("ReturnValue","TextBox");
				Scripter.SetParameterValue("ReturnValue","-1");
			
				// 1. 调用窗体上的过程弹出错误
				if (!PCBType.Equals("M") && !PCBType.Equals("C"))
				{
					PCBType ="";
				}
				
				string UIPCBType = Scripter.GetParameterValue("PCBType").ToString();
				if (UIPCBType=="")
				{
					Scripter.SetControlStyle("PCBType","TextBox");
					Scripter.SetParameterValue("PCBType",PCBType);
				}	
				
				if (Scripter.GetParameterValue("Side") == "A")
					Scripter.RunMethod("AOIAutoScan");
				if (Scripter.GetParameterValue("Side") == "AB")
					Scripter.RunMethod("AOIAutoScan");
				if (Scripter.GetParameterValue("Side") == "B")
					Scripter.RunMethod("AOIAutoScanBSide");
				
				Thread.Sleep(300);
				// 2. 停用定时器	
				if(GetReturnValue()!=0)
				{
					return -1;
				}
				// 扫描已经达到拼板数，扫描提交条码
				if (j + 1 == CurrDt.Rows.Count)
				{
					if (!PCBType.Equals("M") && !PCBType.Equals("C"))
					{
						PCBType ="";
					}
					Scripter.SetControlStyle("PCBType","TextBox");
					Scripter.SetParameterValue("PCBType",PCBType);
					
					Scripter.SetControlStyle("LotSN","TextBox");
					Scripter.SetParameterValue("LotSN","SUBMIT");
					// 1. 调用窗体上的过程弹出错误
					if (Scripter.GetParameterValue("Side") == "A")
						Scripter.RunMethod("AOIAutoScan");
					if (Scripter.GetParameterValue("Side") == "AB")
						Scripter.RunMethod("AOIAutoScan");
					if (Scripter.GetParameterValue("Side") == "B")
						Scripter.RunMethod("AOIAutoScanBSide");
					Thread.Sleep(300);
					// 2. 停用定时器		
					if(GetReturnValue()!=0)
					{
						return -1;
					}								
				}
			}
			return 0;
		}
		#endregion
		#region PCB不良情况
		private int AOITestIsNG()
		{
			//检测AOI是否有漏板
			IsMakeupNumber(CurrDt.Rows.Count);	
			string hideList = "";
			if(GetReturnValue()!=0)
			{
				return -1;
			}
			for (int i=0; i < CurrDt.Rows.Count; i++)
			{
				if (CurrDt.Rows[i]["CheckStatus"].ToString() == "NG")
				{
					Scripter.SetControlStyle("CheckResult","TextBox");
					Scripter.SetParameterValue("CheckResult","NG");	
					
					Scripter.SetControlStyle("LotSN","TextBox");
					Scripter.SetParameterValue("LotSN",CurrDt.Rows[i]["LotSN"].ToString());
					string[] one_NGDesc = CurrDt.Rows[i]["CheckDesc"].ToString().Split(new char[] {'#'});
					if (one_NGDesc.Length<1)
					{
						IsRunning=false;
						return -1;
					}
					for(int j=0; j<one_NGDesc.Length; j++)
					{
						if (string.IsNullOrEmpty(one_NGDesc[j]))
	                    {
	                        continue;
	                    }
						hideList = hideList + one_NGDesc[j].Substring(0,one_NGDesc[j].IndexOf("_")) + ","
											+ one_NGDesc[j].Substring((one_NGDesc[j].IndexOf("_")+1), (one_NGDesc[j].Length - one_NGDesc[j].IndexOf("_") -1) )
											+ ";";
					}
					Scripter.SetControlStyle("HideInfo","TextBox");
					Scripter.SetParameterValue("HideInfo",hideList);	
					Thread.Sleep(200);
					Scripter.RunMethod("BtnIsNG");	
					Thread.Sleep(300);
					if(GetReturnValue()!=0)
					{
						return -1;
					}	
				}
			}
			return 0;
		}
